changeSet.sql:
ALTER TABLE agent_run ADD CONSTRAINT ck_agent_run_start_within CHECK (start_within_seconds IS NULL OR start_within_seconds > 0);
ALTER TABLE agent_run DROP CONSTRAINT ck_agent_run_kind;
ALTER TABLE agent_run ADD CONSTRAINT ck_agent_run_kind CHECK (kind IN ('REVIEW', 'REVIEW_COMPOSE', 'TURN'));
ALTER TABLE agent_run DROP CONSTRAINT ck_agent_run_stop_reason;
ALTER TABLE agent_run ADD CONSTRAINT ck_agent_run_stop_reason CHECK (stop_reason IS NULL
    OR stop_reason IN ('COMPLETED', 'CANCELLED', 'ATTEMPTS_EXHAUSTED', 'NOT_STARTED', 'DEADLINE'));
CREATE OR REPLACE FUNCTION guard_agent_run() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF ROW(NEW.id, NEW.workspace_id, NEW.kind, NEW.band, NEW.created_at, NEW.start_within_seconds)
    IS DISTINCT FROM ROW(OLD.id, OLD.workspace_id, OLD.kind, OLD.band, OLD.created_at, OLD.start_within_seconds) THEN
  RAISE EXCEPTION 'a run''s identity is immutable' USING ERRCODE = '55000';
 END IF;
 IF NEW.concurrency_key IS DISTINCT FROM OLD.concurrency_key AND NOT (OLD.state = 'QUEUED' AND NEW.state = 'QUEUED') THEN
  RAISE EXCEPTION 'only a queued run moves to another subject' USING ERRCODE = '55000';
 END IF;
 IF OLD.state = 'ENDED' THEN
  RAISE EXCEPTION 'an ended run is final' USING ERRCODE = '55000';
 END IF;
 IF NEW.attempt < OLD.attempt THEN
  RAISE EXCEPTION 'a run''s spent attempts never decrease' USING ERRCODE = '23514';
 END IF;
 IF OLD.state = 'QUEUED' AND NEW.state = 'LEASED' THEN
  IF NEW.lease_epoch <> OLD.lease_epoch + 1 THEN
   RAISE EXCEPTION 'a claim takes the next epoch' USING ERRCODE = '23514';
  END IF;
 ELSIF NEW.lease_epoch <> OLD.lease_epoch THEN
  RAISE EXCEPTION 'only a claim changes the epoch' USING ERRCODE = '23514';
 END IF;
 IF OLD.state = 'LEASED' AND NEW.state = 'LEASED' AND NEW.attempt <> OLD.attempt THEN
  RAISE EXCEPTION 'a renewal spends no attempt' USING ERRCODE = '23514';
 END IF;
 IF NEW.deadline IS DISTINCT FROM OLD.deadline
    AND NOT (NEW.deadline IS NULL AND NEW.state = 'QUEUED')
    AND NOT (NEW.deadline IS NOT NULL AND (OLD.deadline IS NULL OR NEW.deadline < OLD.deadline)) THEN
  RAISE EXCEPTION 'a run''s deadline only moves earlier, until a requeue clears it' USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION enforce_mentor_turn_run() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
 turn_status varchar;
 run_state varchar;
BEGIN
 FOR turn_status, run_state IN
  SELECT t.status, r.state FROM mentor_turn t JOIN agent_run r ON r.id = t.run_id
   WHERE (TG_TABLE_NAME = 'mentor_turn' AND t.id = NEW.id) OR (TG_TABLE_NAME = 'agent_run' AND t.run_id = NEW.id)
 LOOP
  IF NOT ((turn_status = 'QUEUED' AND run_state = 'QUEUED')
       OR (turn_status = 'RUNNING' AND run_state = 'LEASED')
       OR (turn_status = 'STOPPED' AND run_state IN ('LEASED', 'ENDED'))
       OR (turn_status IN ('DONE', 'FAILED') AND run_state = 'ENDED')) THEN
   RAISE EXCEPTION 'a turn that is % needs a run that agrees, not one that is %', turn_status, run_state
    USING ERRCODE = '23514';
  END IF;
 END LOOP;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER mentor_turn_run_agrees AFTER INSERT OR UPDATE OF status, run_id ON mentor_turn
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION enforce_mentor_turn_run();
CREATE CONSTRAINT TRIGGER agent_run_turn_agrees AFTER UPDATE OF state ON agent_run
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW WHEN (NEW.kind = 'TURN') EXECUTE FUNCTION enforce_mentor_turn_run();

CREATE FUNCTION forget_mentor_turn_run() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 DELETE FROM agent_run WHERE id = OLD.run_id AND workspace_id = OLD.workspace_id;
 RETURN NULL;
END $$;
CREATE TRIGGER mentor_turn_forgets_run AFTER DELETE ON mentor_turn
 FOR EACH ROW EXECUTE FUNCTION forget_mentor_turn_run();
